package com.futahua.papers.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.system.Os;import android.system.StructStat;import android.provider.DocumentsContract;import android.os.Environment;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Persistent target bindings. Reuses PhoneIndex's census; its write lock must not block file operations. */
final class PhoneTargets {
 private static final ExecutorService EVENTS=Executors.newSingleThreadExecutor();
 static void notifyDeleted(Context c,File f){EVENTS.execute(()->get(c).observedDelete(f));}
 private static PhoneTargets instance;static synchronized PhoneTargets get(Context c){if(instance==null)instance=new PhoneTargets(c.getApplicationContext());return instance;}
 private final Context context;private final SQLiteDatabase db;private final ScheduledExecutorService settle=Executors.newSingleThreadScheduledExecutor();private long lastScanRequest;
 private PhoneTargets(Context c){context=c;db=SQLiteDatabase.openOrCreateDatabase(new File(c.getFilesDir(),"phone-targets.sqlite"),null);db.enableWriteAheadLogging();db.execSQL("CREATE TABLE IF NOT EXISTS targets(id TEXT PRIMARY KEY,path TEXT NOT NULL,native TEXT NOT NULL,revision INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE TABLE IF NOT EXISTS recycled(target TEXT PRIMARY KEY,original TEXT NOT NULL,retained TEXT NOT NULL,digest TEXT NOT NULL)");}
 SQLiteDatabase targetDatabase(){return db;}
 static String identity(File f){try{StructStat s=Os.stat(f.getCanonicalPath());return Long.toString(s.st_dev)+":"+Long.toString(s.st_ino);}catch(Exception e){return "";}}
 private boolean allowed(File f)throws Exception {String p=f.getCanonicalPath();for(File root:PhoneStorage.roots())if(p.equals(root.getCanonicalPath())||p.startsWith(root.getCanonicalPath()+"/"))return f.canRead();return false;}
 private String uri(File f)throws Exception {String p=f.getCanonicalPath();for(File root:PhoneStorage.roots()){String base=root.getCanonicalPath();if(p.equals(base)||p.startsWith(base+"/"))return DocumentsContract.buildDocumentUri("com.android.externalstorage.documents",(root.equals(Environment.getExternalStorageDirectory())?"primary":root.getName())+":"+(p.equals(base)?"":p.substring(base.length()+1))).toString();}throw new IOException("File outside phone storage");}
 synchronized JSONObject track(File f)throws Exception {if(f==null||!f.exists()||!allowed(f))return new JSONObject().put("status","unavailable");String nativeId=identity(f);if(nativeId.isEmpty())return new JSONObject().put("status","unsupported");String id=null;try(Cursor c=db.rawQuery("SELECT id FROM targets WHERE native=? AND deleted=0 LIMIT 1",new String[]{nativeId})){if(c.moveToFirst())id=c.getString(0);}if(id==null){id=UUID.randomUUID().toString();db.execSQL("INSERT INTO targets(id,path,native,revision) VALUES(?,?,?,1)",new Object[]{id,f.getCanonicalPath(),nativeId});}return resolve(id);}
 synchronized JSONObject resolve(String id)throws Exception {String p,key;long revision;int deleted;try(Cursor c=db.rawQuery("SELECT path,native,revision,deleted FROM targets WHERE id=?",new String[]{id})){if(!c.moveToFirst())return new JSONObject().put("targetId",id).put("status","unknown");p=c.getString(0);key=c.getString(1);revision=c.getLong(2);deleted=c.getInt(3);}
 JSONObject result=new JSONObject().put("targetId",id).put("revision",revision);if(deleted!=0)return result.put("status","deleted");File f=new File(p);
 if(f.exists()&&allowed(f)&&key.equals(identity(f))){PhoneIndex.get(context).watchReferenced(f.getParentFile());return result.put("status","present").put("uri",uri(f));}
 File nearby=f.getParentFile();for(int n=0;n<3&&nearby!=null&&!nearby.isDirectory();n++)nearby=nearby.getParentFile();File repaired=nearby==null?null:nearby(nearby,key,0,new int[]{0},System.nanoTime()+150_000_000L);if(repaired!=null){PhoneIndex.get(context).watchReferenced(repaired.getParentFile());db.execSQL("UPDATE targets SET path=?,revision=revision+1 WHERE id=?",new Object[]{repaired.getCanonicalPath(),id});return result.put("revision",revision+1).put("status","present").put("uri",uri(repaired));}
 PhoneIndex index=PhoneIndex.get(context);if(System.currentTimeMillis()-lastScanRequest>60000){lastScanRequest=System.currentTimeMillis();index.refreshSoon();}try(Cursor c=index.targetDatabase().rawQuery("SELECT path FROM files WHERE identity=? LIMIT 32",new String[]{key})){while(c.moveToNext()){File candidate=new File(c.getString(0));if(candidate.exists()&&allowed(candidate)&&key.equals(identity(candidate))){index.watchReferenced(candidate.getParentFile());db.execSQL("UPDATE targets SET path=?,revision=revision+1 WHERE id=?",new Object[]{candidate.getCanonicalPath(),id});return result.put("revision",revision+1).put("status","present").put("uri",uri(candidate));}}}
 return result.put("status",f.exists()?"replacement":"missing");}
 private File nearby(File folder,String key,int depth,int[] count,long deadline)throws Exception {if(depth>3||count[0]>1000||System.nanoTime()>deadline)return null;File[] children=folder.listFiles();if(children==null)return null;for(File child:children){if(++count[0]>1000||System.nanoTime()>deadline)break;if(java.nio.file.Files.isSymbolicLink(child.toPath()))continue;if(key.equals(identity(child))&&allowed(child))return child;if(child.isDirectory()){File found=nearby(child,key,depth+1,count,deadline);if(found!=null)return found;}}return null;}
 synchronized void relocate(File oldFile,File next)throws Exception {String old=oldFile.getCanonicalPath(),dest=next.getCanonicalPath();try(Cursor c=db.rawQuery("SELECT id,path FROM targets WHERE deleted=0",null)){while(c.moveToNext()){String p=c.getString(1);if(!p.equals(old)&&!p.startsWith(old+"/"))continue;File f=new File(dest+p.substring(old.length()));if(f.exists()&&allowed(f))db.execSQL("UPDATE targets SET path=?,native=?,revision=revision+1 WHERE id=?",new Object[]{f.getCanonicalPath(),identity(f),c.getString(0)});}}}
 synchronized void deleted(File source)throws Exception {String p=source.getCanonicalPath();try(Cursor c=db.rawQuery("SELECT id,path FROM targets WHERE deleted=0",null)){while(c.moveToNext())if(c.getString(1).equals(p)||c.getString(1).startsWith(p+"/"))db.execSQL("UPDATE targets SET deleted=1,revision=revision+1 WHERE id=?",new Object[]{c.getString(0)});}}
 void observedDelete(File f){settle.schedule(()->{try{List<String> ids=new ArrayList<>();synchronized(this){try(Cursor c=db.rawQuery("SELECT id,path FROM targets WHERE deleted=0",null)){String p=f.getCanonicalPath();while(c.moveToNext())if(c.getString(1).equals(p)||c.getString(1).startsWith(p+"/"))ids.add(c.getString(0));}}for(String id:ids){JSONObject r=resolve(id);if(!r.optString("status").equals("missing"))continue;File parent=f.getParentFile();if(parent!=null&&parent.canRead()&&parent.list()!=null&&!f.exists())synchronized(this){db.execSQL("UPDATE targets SET deleted=1,revision=revision+1 WHERE id=?",new Object[]{id});}}}catch(Exception ignored){}},2500,TimeUnit.MILLISECONDS);}
 static String recycleDigest(File f)throws Exception {if(java.nio.file.Files.isSymbolicLink(f.toPath()))throw new IOException("Relinked recycle content refused");if(f.isFile())return PhoneContentReuse.digest(f);File[] children=f.listFiles();if(children==null)throw new IOException("Recycled folder unavailable");Arrays.sort(children,Comparator.comparing(File::getName));java.security.MessageDigest h=java.security.MessageDigest.getInstance("SHA-256");for(File child:children)h.update((child.getName()+"|"+child.isDirectory()+"|"+recycleDigest(child)+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:h.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 synchronized File originalFile(String id)throws Exception {try(Cursor c=db.rawQuery("SELECT path FROM targets WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IOException("File reference unavailable");return new File(c.getString(0));}}
 synchronized void retainRecycled(File source,File retained)throws Exception {String old=source.getCanonicalPath();try(Cursor c=db.rawQuery("SELECT id,path FROM targets WHERE deleted=0",null)){while(c.moveToNext()){String p=c.getString(1);if(!p.equals(old)&&!p.startsWith(old+"/"))continue;File saved=new File(retained.getCanonicalPath()+p.substring(old.length()));db.execSQL("INSERT OR REPLACE INTO recycled(target,original,retained,digest) VALUES(?,?,?,?)",new Object[]{c.getString(0),p,saved.getCanonicalPath(),recycleDigest(saved)});}}}
 synchronized JSONObject restore(String id,long revision)throws Exception {
  JSONObject current=resolve(id);if(current.optString("status").equals("present"))return current;if(current.optLong("revision")!=revision)throw new IOException("File changed; refresh before restoring");
  String original,retained,expected;try(Cursor c=db.rawQuery("SELECT original,retained,digest FROM recycled WHERE target=?",new String[]{id})){if(!c.moveToFirst())throw new IOException("No recoverable copy is retained for this entry");original=c.getString(0);retained=c.getString(1);expected=c.getString(2);}
  File destination=new File(original),saved=new File(retained);if(destination.exists())throw new IOException("Original location is occupied; restore refused");if(!destination.getParentFile().isDirectory()||!allowed(destination.getParentFile()))throw new IOException("Original folder unavailable");if(!saved.getCanonicalPath().contains("/.PapersRecycle/")||!saved.exists()||!recycleDigest(saved).equals(expected))throw new IOException("Recycled copy could not be verified");
  java.nio.file.Files.move(saved.toPath(),destination.toPath());if(!recycleDigest(destination).equals(expected))throw new IOException("Restored bytes could not be verified");
  db.execSQL("UPDATE targets SET native=?,deleted=0,revision=revision+1 WHERE id=?",new Object[]{identity(destination),id});db.execSQL("DELETE FROM recycled WHERE target=?",new Object[]{id});PhoneIndex.get(context).refreshSoon();return resolve(id);
 }
 JSONObject call(JSONObject r)throws Exception {String operation=r.getString("operation");if(operation.equals("phone-target-restore"))return restore(r.getString("targetId"),r.getLong("expectedRevision"));if(operation.equals("phone-target-track"))return track(PhoneStorage.file(Uri.parse(r.getString("uri"))));if(operation.equals("phone-target-relocate")){relocate(PhoneStorage.file(Uri.parse(r.getString("oldUri"))),PhoneStorage.file(Uri.parse(r.getString("newUri"))));return new JSONObject().put("ok",true);}return resolve(r.getString("targetId"));}
}
